    },
    {
      problem: 'a minAge rule is attached to a text field',
      key: 'minAgeOnText',
      extra: item({ key: 'minAgeOnText', type: 'text', rules: [rule({ kind: 'minAge', years: 18 })] }),
    },
    {
      problem: 'a minLength rule has no value',
