export type FieldType = 'text' | 'number' | 'select' | 'date' | 'checkbox';

export interface SelectOption { value: string; label: string; sortOrder: number }

export type ValidationRule = { message?: string } & (
  | { kind: 'minLength' | 'maxLength'; value: number }
  | { kind: 'min' | 'max'; value: number }
  | { kind: 'pattern'; value: string }
  | { kind: 'minAge'; years: number }
  | { kind: 'yearRange'; maxYearsOld: number; maxYearsAhead: number }
  | { kind: 'rutCheckDigit' }
);

export interface FieldConfig {
  key: string;
  type: FieldType;
  label: string;
  helpText?: string;
  placeholder?: string;
  isRequired: boolean;
  sortOrder: number;
  errorMessage: string;
  requiredMessage?: string;
  options?: SelectOption[];
  rules: ValidationRule[];
}

/** Value held by the form MODEL for a field: never null. */
export type RawValue = string | boolean;
export type RawValues = Record<string, RawValue>;
/** Value emitted by step 1 (spec 7.3). */
export type OutputValue = string | number | boolean | null;
=== form-values
import { FieldConfig, OutputValue, RawValue, RawValues } from './field-config';
import { isEmpty } from './validate-field';

export function initialValue(cfg: FieldConfig): RawValue {
  return cfg.type === 'checkbox' ? false : '';
}

/** Builds model values for the CURRENT config, taking stored values when compatible. Keys not configured are dropped. */
export function hydrate(configs: FieldConfig[], stored: Record<string, unknown> | null | undefined): RawValues {
  const out: RawValues = {};
  for (const cfg of configs) {
    const s = stored?.[cfg.key];
    if (cfg.type === 'checkbox') out[cfg.key] = s === true;
    else if (typeof s === 'string') out[cfg.key] = s;
    else if (typeof s === 'number' && Number.isFinite(s)) out[cfg.key] = String(s);
    else out[cfg.key] = '';
  }
  return out;
}

/** Step 1 output (spec 7.3): trimmed text, integer, option value, ISO date, boolean; empty optional -> null. */
export function toOutput(configs: FieldConfig[], values: RawValues): Record<string, OutputValue> {
  const out: Record<string, OutputValue> = {};
  for (const cfg of configs) {
    const v = values[cfg.key] ?? initialValue(cfg);
    if (cfg.type === 'checkbox') { out[cfg.key] = v === true; continue; }
    if (isEmpty(cfg, v)) { out[cfg.key] = null; continue; }
    const s = (v as string).trim();
    out[cfg.key] = cfg.type === 'number' ? Number(s) : s;
  }
  return out;
}
=== validate-field
import { FieldConfig, RawValue } from './field-config';

const ISO = /^(\d{4})-(\d{2})-(\d{2})$/;

export interface YMD { y: number; m: number; d: number }

/** Strict ISO date parse (rejects 2026-02-31). */
export function parseIsoDate(s: string): YMD | null {
  const m = ISO.exec(s);
  if (!m) return null;
  const [y, mo, d] = [+m[1], +m[2], +m[3]];
  const dt = new Date(Date.UTC(y, mo - 1, d));
  return dt.getUTCFullYear() === y && dt.getUTCMonth() === mo - 1 && dt.getUTCDate() === d ? { y, m: mo, d } : null;
}

/** Completed years on today's LOCAL date. 29 Feb birthdays turn a year older on 1 Mar in non-leap years. */
export function ageOn(birth: YMD, today: Date): number {
  const ty = today.getFullYear(), tm = today.getMonth() + 1, td = today.getDate();
  return ty - birth.y - (tm < birth.m || (tm === birth.m && td < birth.d) ? 1 : 0);
}

export function isEmpty(cfg: FieldConfig, v: RawValue): boolean {
  if (cfg.type === 'checkbox') return v !== true;
  return typeof v !== 'string' || v.trim() === '';
}

/** Returns the message of the first failing check, or null. `required` first, then rules in config order. */
export function validateField(cfg: FieldConfig, v: RawValue, today: Date): string | null {
  const empty = isEmpty(cfg, v);
  if (empty) return cfg.isRequired ? (cfg.requiredMessage ?? cfg.errorMessage) : null; // optional empty skips all rules
  const s = typeof v === 'string' ? v.trim() : '';
  if (cfg.type === 'number') {
    const n = Number(s);
    if (!Number.isFinite(n) || !Number.isInteger(n)) return cfg.errorMessage;
  }
  if (cfg.type === 'date') {
    if (!parseIsoDate(s)) return cfg.errorMessage;
  }
  if (cfg.type === 'select' && !cfg.options?.some(o => o.value === s)) return cfg.errorMessage;
  for (const r of cfg.rules) {
    const msg = r.message ?? cfg.errorMessage;
    switch (r.kind) {
      case 'minLength': if (s.length < r.value) return msg; break;
      case 'maxLength': if (s.length > r.value) return msg; break;
      case 'min': if (Number(s) < r.value) return msg; break;
      case 'max': if (Number(s) > r.value) return msg; break;
      case 'pattern': if (!new RegExp(`^(?:${r.value})$`).test(s)) return msg; break;
      case 'minAge': if (ageOn(parseIsoDate(s)!, today) < r.years) return msg; break;
      case 'yearRange': {
        const y = today.getFullYear(), n = Number(s);
        if (n < y - r.maxYearsOld || n > y + r.maxYearsAhead) return msg;
        break;
      }
      case 'rutCheckDigit': break; // out of scope for the spike
    }
  }
  return null;
}

